package org.brightstats.desktop;
import java.util.*;
import java.util.function.*;
import javafx.scene.Group;
import javafx.scene.Node;
import javafx.scene.control.Tooltip;
import javafx.scene.input.MouseEvent;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.*;
import javafx.scene.text.*;
import org.brightstats.model.*;
import org.brightstats.model.TypedDiagram.Document;
import org.brightstats.model.DiagramGeometry.Point;

/** Interactive projection of an immutable diagram; dragging commits one history transaction. */
final class TypedDiagramView extends Pane {
    private Document document,dragStart;private final Set<String> selected=new LinkedHashSet<>();
    private final Group links=new Group(),nodes=new Group(),notes=new Group();private final Map<String,Group> nodeViews=new HashMap<>(),noteViews=new HashMap<>();
    private final Consumer<Document> commit;private final Consumer<Set<String>> selection;private final Consumer<String> edit;
    private double originX,originY,startX,startY,zoom=1;private boolean dragged;
    TypedDiagramView(Document document,Consumer<Document> commit,Consumer<Set<String>> selection,Consumer<String> edit){this.document=document;this.commit=commit;this.selection=selection;this.edit=edit;getChildren().setAll(links,nodes,notes);getProperties().put("brightstats.redraw",(Runnable)this::render);setFocusTraversable(true);setAccessibleText(document.family()+" typed statistical diagram");setOnMouseClicked(event->{if(event.getTarget()==this){selected.clear();selection.accept(Set.of());render();requestFocus();}});render();}
    Document document(){return document;}Set<String> selected(){return Set.copyOf(selected);}
    void show(Document document,Set<String> selection){this.document=document;selected.clear();selected.addAll(selection);render();}
    void zoom(double value){zoom=value;}
    private void render(){var palette=ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent());setStyle("-fx-background-color:"+palette.background()+";");var bounds=DiagramGeometry.bounds(document);originX=40-bounds.x();originY=40-bounds.y();setPrefSize(bounds.width()+80,bounds.height()+80);for(Group layer:List.of(links,nodes,notes)){layer.setTranslateX(originX);layer.setTranslateY(originY);}nodes.getChildren().clear();notes.getChildren().clear();nodeViews.clear();noteViews.clear();renderLinks();for(var node:document.nodes())if(node.type()!=ElementType.ROOT){Group view=nodeView(node);nodeViews.put(node.id(),view);nodes.getChildren().add(view);}for(var note:document.annotations()){Group view=noteView(note);noteViews.put(note.id(),view);notes.getChildren().add(view);}positions();}
    private void positions(){for(var entry:nodeViews.entrySet()){Point p=DiagramGeometry.position(document,entry.getKey());entry.getValue().setLayoutX(p.x());entry.getValue().setLayoutY(p.y());}for(var entry:noteViews.entrySet()){var note=document.annotations().stream().filter(value->value.id().equals(entry.getKey())).findFirst().orElseThrow();Point p=DiagramGeometry.annotation(document,note);entry.getValue().setLayoutX(p.x());entry.getValue().setLayoutY(p.y());}}
    private Group nodeView(org.brightstats.model.TypedDiagram.Node node){var size=DiagramGeometry.size(node);Shape shape;if(node.type()==ElementType.REGRESSION_INTERCEPT)shape=new Polygon(0.,-24.,24.,22.,-24.,22.);else if(size.ellipse())shape=new Ellipse(size.width()/2,size.height()/2);else{Rectangle rectangle=new Rectangle(-size.width()/2,-size.height()/2,size.width(),size.height());rectangle.setArcWidth(8);rectangle.setArcHeight(8);shape=rectangle;}shape.setFill(color(node));shape.setStroke(selected.contains(node.id())?Color.web(ModelDiagramGraphics.palette(UiAppearance.theme(),UiAppearance.current().accent()).accent()):Color.web("#4b677b"));shape.setStrokeWidth(selected.contains(node.id())?3:1.5);Group view=new Group(shape);if(node.type()!=ElementType.DONGLE){String label=node.label().isBlank()?node.type()==ElementType.GAUSSIAN_COPULA?"GC":node.type()==ElementType.CBSEM_ERROR_TERM?"e":"x²":node.label();Text text=new Text(label);text.setFont(Font.font("System",FontWeight.SEMI_BOLD,node.type().observed()?12:13));text.setFill(readable(color(node)));text.setWrappingWidth(Math.max(30,size.width()-14));text.setTextAlignment(TextAlignment.CENTER);text.setX(-Math.max(30,size.width()-14)/2);text.setY(-Math.min(12,text.getLayoutBounds().getHeight()/2)+10);text.setMouseTransparent(true);view.getChildren().add(text);}view.setFocusTraversable(true);view.setAccessibleText(node.label()+", "+node.type());String description=node.type().toString();if(node.properties().has("column"))description+="\nData column: "+node.properties().get("column").toString();Tooltip.install(view,new Tooltip(description));interact(view,node.id());return view;}
    private Group noteView(org.brightstats.model.TypedDiagram.Annotation note){Rectangle background=new Rectangle(note.width(),note.height());background.setFill(note.type()==ElementType.POSTIT?Color.web("#FFF1B8"):Color.web("#FFFFFF",.92));background.setStroke(selected.contains(note.id())?Color.web("#007C91"):note.type()==ElementType.POSTIT?Color.web("#B89A39"):Color.TRANSPARENT);background.setStrokeWidth(selected.contains(note.id())?3:1);Text text=new Text(8,18,note.text());text.setFont(Font.font("System",12));text.setWrappingWidth(note.width()-16);text.setMouseTransparent(true);Group view=new Group(background,text);view.setClip(new Rectangle(note.width(),note.height()));view.setFocusTraversable(true);view.setAccessibleText(note.type()+": "+note.text());Tooltip.install(view,new Tooltip(note.text()));interact(view,note.id());return view;}
    private void interact(Group view,String id){view.setOnMousePressed(event->{if(!event.isControlDown()&&!selected.contains(id))selected.clear();if(event.isControlDown()&&selected.contains(id))selected.remove(id);else selected.add(id);selection.accept(Set.copyOf(selected));dragStart=document;startX=event.getSceneX();startY=event.getSceneY();dragged=false;requestFocus();event.consume();});view.setOnMouseDragged(event->{if(dragStart==null)return;double dx=(event.getSceneX()-startX)/zoom,dy=(event.getSceneY()-startY)/zoom;try{document=dragStart.move(selected,dx,dy);dragged|=Math.abs(dx)+Math.abs(dy)>1;positions();renderLinks();}catch(IllegalArgumentException ignored){}event.consume();});view.setOnMouseReleased(event->{if(dragStart!=null){Document result=document;dragStart=null;if(dragged)commit.accept(result);else render();}event.consume();});view.setOnMouseClicked(event->{if(event.getClickCount()==2)edit.accept(id);event.consume();});}
    private void renderLinks(){links.getChildren().clear();for(var link:document.links()){List<Point> points=DiagramGeometry.path(document,link);Color stroke=selected.contains(link.id())?Color.web("#007C91"):link.type().covariance()?Color.web("#7C478F"):link.type().modifier()?Color.web("#B65C16"):Color.web("#445B6B");Group view=new Group();Shape line;if(link.type().covariance()){Point a=points.getFirst(),c=points.get(1),b=points.getLast();line=new QuadCurve(a.x(),a.y(),c.x(),c.y(),b.x(),b.y());line.setFill(Color.TRANSPARENT);}else{Polyline path=new Polyline();for(var point:points){path.getPoints().add(point.x());path.getPoints().add(point.y());}line=path;}line.setStroke(stroke);line.setStrokeWidth(selected.contains(link.id())?3:1.7);if(link.type().modifier())line.getStrokeDashArray().setAll(7.,4.);view.getChildren().add(line);view.getChildren().add(arrow(points.get(points.size()-2),points.getLast(),stroke));if(link.type().covariance())view.getChildren().add(arrow(points.get(1),points.getFirst(),stroke));view.setOnMouseClicked(event->{if(!event.isControlDown())selected.clear();selected.add(link.id());selection.accept(Set.copyOf(selected));if(event.getClickCount()==2)edit.accept(link.id());else renderLinks();event.consume();});view.setAccessibleText(link.type()+": "+document.node(link.source()).label()+" to "+document.node(link.target()).label());links.getChildren().add(view);}}
    private static Polygon arrow(Point from,Point to,Color color){double angle=Math.atan2(to.y()-from.y(),to.x()-from.x()),length=10,width=4;Polygon arrow=new Polygon(to.x(),to.y(),to.x()-length*Math.cos(angle)+width*Math.sin(angle),to.y()-length*Math.sin(angle)-width*Math.cos(angle),to.x()-length*Math.cos(angle)-width*Math.sin(angle),to.y()-length*Math.sin(angle)+width*Math.cos(angle));arrow.setFill(color);arrow.setMouseTransparent(true);return arrow;}
    private static Color readable(Color color){double luminance=.2126*linear(color.getRed())+.7152*linear(color.getGreen())+.0722*linear(color.getBlue());return luminance>.179?Color.BLACK:Color.WHITE;}
    private static double linear(double value){return value<=.04045?value/12.92:Math.pow((value+.055)/1.055,2.4);}
    private static Color color(org.brightstats.model.TypedDiagram.Node node){if(node.properties().has("color")&&node.properties().get("color").isJsonPrimitive()&&node.properties().get("color").getAsJsonPrimitive().isString()){String value=node.properties().get("color").getAsString();if(value.matches("#[0-9A-Fa-f]{6}"))return Color.web(value);}if(node.type()==ElementType.DONGLE)return Color.web("#B65C16");if(node.type()==ElementType.GAUSSIAN_COPULA)return Color.web("#FFE3C1");if(node.type()==ElementType.QUADRATIC_EFFECT||node.type()==ElementType.PROCESS_MODEL_QUADRATIC_EFFECT)return Color.web("#F1D9F4");if(node.type()==ElementType.CBSEM_ERROR_TERM)return Color.web("#F0F2F4");if(node.type()==ElementType.PROCESS_MODEL_CONTROL_VARIABLE)return Color.web("#E3EAD3");return node.type().observed()?Color.web("#FFF1B8"):Color.web("#D8E9F6");}
}
